import {labs,moduleNames,subnetTask,isQuiz} from './labs.js';
import {createState,execute,prompt,objectives,ipv4,ipv6,maskValid} from './engine.js';
import {validProgress} from './progress.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='wasla-itn-v1';let progress={version:1,labs:{},last:'2.5.5'};let storageOK=true;
try{const p=JSON.parse(localStorage.getItem(STORE));if(validProgress(p))progress=p;}catch{storageOK=false;}
let lab,s,key,record,history=[],historyIndex=0,animationTimer;
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3500);}
function persist(){progress.last=lab.id;progress.labs[lab.id]=record;try{localStorage.setItem(STORE,JSON.stringify(progress));}catch{storageOK=false;}renderProgress();}
function replayAction(a){if(a.type==='device'){const d=s.devices[a.key];if(!d||d.type!=='pc'||!a.values)return;const v=a.values;if(ipv4(v.ip)===null||!maskValid(v.mask)||ipv4(v.gateway)===null||!ipv6(v.ipv6)||!ipv6(v.gateway6)||v.prefix!==64)return;Object.assign(d,{ip:v.ip,mask:v.mask,gateway:v.gateway,ipv6:v.ipv6,gateway6:v.gateway6,prefix:64});s.pingOK=false;s.traceOK=false;}
if(a.type==='link'&&Number.isInteger(a.index)&&a.index>=0&&a.index<4){s.links[a.index]=!!a.up;s.pingOK=false;s.traceOK=false;}
if(a.type==='quiz'&&lab.quiz)s.quizOK=a.answer===lab.quiz[2];
if(a.type==='observe')s.observed=true;
if(a.type==='subnet'&&Array.isArray(a.answers)){s.subnetAnswers=a.answers;s.subnetOK=verifySubnet(a.answers);}}
function runRecord(){s=createState(lab);const timeline=[...record.commands.map(c=>({...c,type:'command'})),...record.actions].sort((a,b)=>a.seq-b.seq);for(const a of timeline){if(a.type==='command')execute(s,a.key,a.raw);else replayAction(a);} }
function action(a){if(record.actions.length>=3000)return toast('بلغت الجلسة حد التغييرات؛ صدّر التقدّم ثم أعد النشاط.');a.seq=++record.seq;record.actions.push(a);replayAction(a);renderObjectives();persist();renderTopology();renderCatalog();}
function renderProgress(){let done=0;for(const l of labs){const r=progress.labs[l.id];if(r?.completed)done++;}$('course-progress').textContent=`${done} من ${labs.length} نشاطًا مكتملًا`;$('course-bar').style.width=`${done/labs.length*100}%`;}
function renderCatalog(){const q=$('search').value.toLowerCase().trim(),mod=$('module').value;const visible=labs.filter(l=>(mod==='all'||l.module===Number(mod))&&`${l.id} ${l.title} ${l.en}`.toLowerCase().includes(q));$('count').textContent=visible.length;$('catalog').innerHTML=visible.map(l=>`<button class="activity ${l.id===lab.id?'selected':''}" data-id="${l.id}" ${l.id===lab.id?'aria-current="page"':''}><span class="num" dir="ltr">${l.id.replace('-P','ᴾ')}</span><span><strong>${l.title}</strong><small>${moduleNames[l.module]}</small></span>${progress.labs[l.id]?.completed?'<span class="done">✓</span>':''}</button>`).join('')||'<p class="empty">لا توجد أنشطة مطابقة.</p>';
$('catalog').querySelectorAll('button').forEach(b=>b.onclick=()=>loadLab(b.dataset.id));}
function loadLab(id){clearTimeout(animationTimer);lab=labs.find(l=>l.id===id)||labs[3];record=progress.labs[lab.id]||{seq:0,commands:[],actions:[],completed:false};runRecord();key=['switch','navigation'].includes(lab.kind)?'S1':isQuiz(lab)||['connect','physical','troubleshoot'].includes(lab.kind)?'PC-A':'R1';history=[];historyIndex=0;$('title').textContent=lab.title;$('subtitle').textContent=lab.description;$('crumb').textContent=`النشاط ${lab.id}`;$('device-select').innerHTML=Object.keys(s.devices).map(k=>`<option>${k}</option>`).join('');$('feedback').textContent='';$('terminal').textContent='WASLA NETWORK LAB · Educational IOS subset\nType ? for supported commands.\nSession restored; configurations are saved locally.\n\n';renderCatalog();renderObjectives();renderTopology();renderTools();renderPractice();renderLearning();selectDevice(key);setView('terminal');persist();}
function renderObjectives(){const list=objectives(lab,s),complete=list.filter(x=>x.ok).length,pct=Math.round(complete/list.length*100);$('score').textContent=pct+'%';$('lab-bar').style.width=pct+'%';$('objectives').innerHTML=list.map((x,i)=>`<div class="objective ${x.ok?'complete':''}"><i>${x.ok?'✓':i+1}</i><span>${esc(x.text)}</span></div>`).join('');record.completed=pct===100;}
const points={'PC-A':[65,150],S1:[190,150],R1:[340,105],S2:[490,150],'PC-B':[615,150]},edges=[['PC-A','S1'],['S1','R1'],['R1','S2'],['S2','PC-B']];
function renderTopology(animate=false){const routed=s.devices.R1.interfaces;const live=s.links.map((x,i)=>x&&(i===1?routed['gigabitethernet0/0'].up:i===2?routed['gigabitethernet0/1'].up:true));$('topology').innerHTML=`<svg viewBox="0 0 680 250" role="img" aria-label="شبكة تدريبية: PC-A وS1 وR1 وS2 وPC-B"><text x="35" y="32" class="wire-label">LAN A · 192.168.10.0/24</text><text x="440" y="32" class="wire-label">LAN B · 192.168.20.0/24</text>${edges.map(([a,b],i)=>`<line x1="${points[a][0]}" y1="${points[a][1]}" x2="${points[b][0]}" y2="${points[b][1]}" class="wire ${live[i]?'':'down'}"/><text class="wire-label" x="${(points[a][0]+points[b][0])/2-20}" y="${(points[a][1]+points[b][1])/2+24}">${i===1?'G0/0':i===2?'G0/1':'Fa0/1'}</text>`).join('')}${animate?'<circle r="5" class="packet packet-flight" style="offset-path:path(\'M65 150 L190 150 L340 105 L490 150 L615 150\')"/>':''}${Object.entries(points).map(([k,[x,y]])=>`<g class="node ${key===k?'selected':''}" data-device="${k}" role="button" tabindex="0" aria-label="اختيار ${k}" transform="translate(${x},${y})"><rect x="-30" y="-27" width="60" height="54" rx="10"/><text class="symbol" text-anchor="middle" y="8">${k==='R1'?'⇄':k.startsWith('PC')?'▣':'⇆'}</text><text text-anchor="middle" y="48">${esc(s.devices[k].name)}</text></g>`).join('')}</svg>`;
$('topology').querySelectorAll('.node').forEach(n=>{n.onclick=()=>selectDevice(n.dataset.device);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectDevice(n.dataset.device);}};});}
function renderTools(){$('network-tools').innerHTML=`<span>الوصلة</span><select id="link-select" aria-label="اختيار الوصلة">${edges.map(([a,b],i)=>`<option value="${i}">${a} ↔ ${b}</option>`).join('')}</select><select id="cable" aria-label="نوع الكابل"><option value="straight">Copper Straight-Through</option><option value="console">Console</option><option value="fiber">Fiber</option></select><button class="secondary" id="link-on">توصيل</button><button class="secondary" id="link-off">فصل</button>`;$('link-on').onclick=()=>{if($('cable').value!=='straight')return toast('منافذ Ethernet في هذه الشبكة التدريبية تستخدم كابلًا نحاسيًا مستقيمًا.');action({type:'link',index:Number($('link-select').value),up:true});toast('تم توصيل الوصلة.');};$('link-off').onclick=()=>{action({type:'link',index:Number($('link-select').value),up:false});toast('تم فصل الوصلة.');};}
function selectDevice(k){key=k;$('device-select').value=k;$('prompt').textContent=prompt(s.devices[key]);renderTopology();renderDevice();}
function setView(view){for(const v of ['terminal','device','learning'])$(`${v}-view`).hidden=v!==view;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function renderDevice(){const d=s.devices[key];if(d.type!=='pc'){$('device-view').innerHTML=`<p>الجهاز <code>${esc(d.name)}</code> · ${d.type==='router'?'موجّه':'مبدّل'}</p><p>استخدم طرفية CLI لتهيئة هذا الجهاز. ادخل أولًا <code>enable</code> ثم <code>configure terminal</code>.</p><table><thead><tr><th>الواجهة</th><th>IPv4</th><th>IPv6</th><th>الحالة الإدارية</th></tr></thead><tbody>${Object.entries(d.interfaces).map(([p,v])=>`<tr><td dir="ltr">${esc(p)}</td><td dir="ltr">${esc(v.ip)}</td><td dir="ltr">${esc(v.ipv6||'—')}</td><td>${v.up?'مفعّلة':'متوقفة'}</td></tr>`).join('')}</tbody></table><p>حالة الحفظ: ${d.saved?'محفوظة بعد آخر تعديل':'لم تُحفظ بعد آخر تعديل'}</p>`;return;}
$('device-view').innerHTML=`<p>تهيئة الحاسب <code>${key}</code> · التغييرات تؤثر مباشرةً في اختبار الاتصال.</p><form id="device-form">${[['ip','عنوان IPv4'],['mask','قناع الشبكة'],['gateway','البوابة الافتراضية IPv4'],['ipv6','عنوان IPv6 /64'],['gateway6','البوابة الافتراضية IPv6']].map(([k,label])=>`<label>${label}<input name="${k}" value="${esc(d[k])}" required autocomplete="off" spellcheck="false"></label>`).join('')}<button class="primary" type="submit">تطبيق الإعدادات</button><div id="device-error" role="status"></div></form>`;
$('device-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));Object.keys(values).forEach(k=>values[k]=values[k].trim());if(ipv4(values.ip)===null||!maskValid(values.mask)||ipv4(values.gateway)===null||!ipv6(values.ipv6)||!ipv6(values.gateway6)){$('device-error').textContent='تحقق من صحة العناوين وقناع الشبكة.';return;}values.prefix=64;action({type:'device',key,values});toast('تم تطبيق إعدادات الحاسب.');renderDevice();};}
function appendTerminal(text){$('terminal').textContent+=text+'\n';if($('terminal').textContent.length>60000)$('terminal').textContent=$('terminal').textContent.slice(-45000);$('terminal').scrollTop=$('terminal').scrollHeight;}
function submitCommand(raw){if(raw.length>200)return toast('الحد الأقصى للأمر 200 محرف.');if(record.commands.length>=3000)return toast('بلغت الجلسة حد الأوامر؛ صدّر التقدّم ثم أعد النشاط.');const pre=prompt(s.devices[key]);const out=execute(s,key,raw);record.commands.push({key,raw,seq:++record.seq});appendTerminal(`${pre} ${raw}${out?'\n'+out:''}`);$('prompt').textContent=prompt(s.devices[key]);renderObjectives();persist();renderTopology(s.pingOK&&raw.toLowerCase().startsWith('ping '));renderDevice();renderEvents();}
function renderEvents(){const el=$('events');if(el)el.innerHTML=s.events.map(x=>`<div class="event" dir="ltr">${esc(x)}</div>`).join('');}
function observe(){const before=key;key='PC-A';const target=lab.kind==='ndp'?'2001:db8:20::10':'192.168.20.10';submitCommand(`ping ${target}`);action({type:'observe'});selectDevice(before);renderTopology(s.pingOK);clearTimeout(animationTimer);animationTimer=setTimeout(()=>renderTopology(),4000);renderEvents();}
function verifySubnet(answers){if(lab.kind==='ipv6subnet'){return answers.length===3&&answers.every((v,i)=>v.network?.trim().toLowerCase()===`2001:db8:${i.toString(16)}::`&&String(v.prefix)==='64');}const expected=subnetTask(lab).rows;return answers.length===expected.length&&answers.every((v,i)=>v.network?.trim()===expected[i].network&&Number(v.prefix)===expected[i].prefix&&v.broadcast?.trim()===expected[i].broadcast);}
function renderPractice(){const type=lab.kind;if(['subnet','vlsm','ipv6subnet'].includes(type)){renderSubnet();return;}
if(isQuiz(lab)){$('practice-title').textContent='تتبّع وفهم';$('practice').innerHTML=`<p>شغّل تتبّعًا تعليميًا لتبادل البيانات، ثم أجب عن السؤال.</p><button class="secondary full" id="observe">▷ تشغيل التتبّع</button><div id="events"></div><h3>${esc(lab.quiz[0])}</h3><form id="quiz-form"><label>اختر الإجابة<select name="answer"><option value="">— اختر —</option>${lab.quiz[1].map((x,i)=>`<option value="${i}">${esc(x)}</option>`).join('')}</select></label><button class="primary" type="submit">تحقّق من الفهم</button><div id="quiz-result" class="result" role="status"></div></form>`;$('observe').onclick=observe;$('quiz-form').onsubmit=e=>{e.preventDefault();const value=e.target.elements.answer.value;if(value==='')return;action({type:'quiz',answer:Number(value)});$('quiz-result').textContent=s.quizOK?`إجابة صحيحة. ${lab.quiz[3]}`:'حاول مجددًا، وراجع الشرح وتسلسل الأحداث.';renderCatalog();};renderEvents();return;}
$('practice-title').textContent='اختبار الاتصال';$('practice').innerHTML=`<p>الحاسب PC-A في الشبكة 10 والحاسب PC-B في الشبكة 20. انتقل إلى إعدادات الحاسب أو طرفية الموجّه لإصلاح العطل.</p><table><tr><th>الجهاز</th><th>العنوان المستهدف</th></tr><tr><td>PC-A</td><td dir="ltr">192.168.10.10/24</td></tr><tr><td>PC-B</td><td dir="ltr">192.168.20.10/24</td></tr></table><button id="test-ping" class="primary">اختبار PC-A → PC-B</button><p class="muted" style="padding:8px 0 0">يعرض الاختبار نتيجته في الطرفية. استخدمها لتحديد خطوتك التالية.</p><div id="events"></div>`;$('test-ping').onclick=()=>{selectDevice('PC-A');setView('terminal');submitCommand(`ping ${type==='ipv6'?'2001:db8:20::10':'192.168.20.10'}`);};renderEvents();}
function renderSubnet(){const v6=lab.kind==='ipv6subnet',task=v6?null:subnetTask(lab),rows=v6?[{hosts:'LAN 1'},{hosts:'LAN 2'},{hosts:'LAN 3'}]:task.rows;$('practice-title').textContent=v6?'مخطط شبكات IPv6':'مخطط العنونة';$('practice').innerHTML=`<p>${v6?'ابدأ من 2001:db8::/48. اكتب أول ثلاث شبكات /64 بالتدوين المضغوط، بدءًا من المعرّف 0 ثم 1 ثم 2.':`قسّم <code>${task.network}</code> ${lab.kind==='vlsm'?'بأقنعة متغيّرة مع تخصيص متتالٍ من أصغر عنوان، الأكبر أولًا.':'إلى أربع شبكات متساوية تستوعب كل منها 50 مضيفًا؛ أكمل أول ثلاث شبكات.'}`}</p><form id="subnet-form">${rows.map((r,i)=>`<fieldset style="border:1px solid #34435b;border-radius:7px;margin:12px 0;padding:10px"><legend>${v6?r.hosts:`شبكة ${i+1} · ${r.hosts} مضيفًا`}</legend><label>عنوان الشبكة<input name="network${i}" dir="ltr" required placeholder="${v6?'2001:db8:0::':'192.168.x.x'}" value="${esc(s.subnetAnswers[i]?.network||'')}"></label><label>طول البادئة<input name="prefix${i}" type="number" min="1" max="${v6?128:32}" required placeholder="${v6?'64':'26'}" value="${esc(s.subnetAnswers[i]?.prefix||'')}"></label>${v6?'':`<label>عنوان البث<input name="broadcast${i}" dir="ltr" required value="${esc(s.subnetAnswers[i]?.broadcast||'')}"></label>`}</fieldset>`).join('')}<button class="primary" type="submit">فحص مخطط العنونة</button><div id="subnet-result" class="result" role="status"></div></form>`;$('subnet-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),answers=rows.map((_,i)=>({network:fd.get(`network${i}`),prefix:fd.get(`prefix${i}`),broadcast:fd.get(`broadcast${i}`)||''}));action({type:'subnet',answers});$('subnet-result').textContent=s.subnetOK?'جميع الشبكات صحيحة. أحسنت الحساب!':'توجد قيمة غير صحيحة. راجع حجم الكتلة وحدود الشبكة وطول البادئة.';renderCatalog();};}
const hints={switch:'enable\nconfigure terminal\nhostname Access-SW\ninterface vlan 1\nip address 192.168.10.2 255.255.255.0\nno shutdown\nexit\nip default-gateway 192.168.10.1\nend\ncopy running-config startup-config',router:'enable\nconfigure terminal\ninterface g0/0\nip address 192.168.10.1 255.255.255.0\nno shutdown\nexit\ninterface g0/1\nip address 192.168.20.1 255.255.255.0\nno shutdown\nend\ncopy running-config startup-config',ipv6:'enable\nconfigure terminal\nipv6 unicast-routing\ninterface g0/0\nipv6 address 2001:db8:10::1/64\nexit\ninterface g0/1\nipv6 address 2001:db8:20::1/64\nend\nshow ipv6 interface brief',security:'enable\nconfigure terminal\nhostname Edge-R1\nip domain-name lab.local\nenable secret Practice123\nusername admin secret Practice123\ncrypto key generate rsa modulus 2048\nip ssh version 2\nline vty 0 4\nlogin local\ntransport input ssh\nend\ncopy running-config startup-config',navigation:'enable\nconfigure terminal\nend\nshow ip interface brief'};
function renderLearning(){const hint=hints[lab.kind]||(lab.kind==='challenge'?hints.router:null)||(['subnet','vlsm'].includes(lab.kind)?'حجم الكتلة = 2^(32 - طول البادئة).\nللمضيفين العاديين: 2^h - 2.\nاختر أقل h يستوعب عدد المضيفين.\nعنوان البث = عنوان الشبكة التالية - 1.':lab.kind==='ipv6subnet'?'توسيع 2001:db8::/48 يثبّت أول ثلاث مجموعات.\nمعرّف الشبكة الفرعية هو المجموعة الرابعة.\nاستخدم 0 ثم 1 ثم 2 مع /64.':'PC-A → إعدادات الجهاز\nIPv4: 192.168.10.10\nMask: 255.255.255.0\nGateway: 192.168.10.1\n\nipconfig\nping 192.168.20.10\ntracert 192.168.20.10\narp -a');$('hints').innerHTML=`<pre>${esc(hint)}</pre>`;
$('learning-view').innerHTML=`<h2>${esc(lab.title)} — تمرين عربي مستقل</h2><p>${esc(lab.description)}</p><ol><li>راجع الأهداف قبل تعديل الإعدادات. يعرض المخطط شبكة تعليمية مشتركة وليست نسخة مستخرجة من الملف الأصلي.</li><li>اختر الجهاز من المخطط أو القائمة. أجهزة الحاسب تستخدم تبويب الإعدادات، والموجّهات والمبدّلات تستخدم الطرفية.</li><li>الأوامر المتاحة محدودة؛ اكتب <code>?</code> لعرض الصيغ التي يدعمها النموذج. تستخدم تمارين الأمان أسرارًا تدريبية فقط؛ لا تدخل كلمات مرور حقيقية.</li><li>نفّذ اختبار الاتصال بعد آخر تعديل ثم افحص تقدّمك. يُحفظ العمل في هذا المتصفح ويمكن تصديره.</li></ol><p>الملف المرجعي من فهرسك: <code>${esc(lab.filename)}</code></p><p>حدود النسخة: لا تشغيل لملفات PKA/PKT، ولا محاكاة IOS كاملة أو لاسلكي أو وضع فيزيائي ثلاثي الأبعاد. تتبع الحزمة عرض تعليمي مرتب للأحداث؛ ليس التقاطًا فعليًا للحزم. نشاط ${lab.id} يستخدم تمرينًا موضوعيًا مبسطًا وليس تقييم Cisco الرسمي.</p>`;}
$('cli-form').onsubmit=e=>{e.preventDefault();const raw=$('command').value.trim();if(!raw)return;history.push(raw);historyIndex=history.length;submitCommand(raw);$('command').value='';};
$('command').onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.max(0,Math.min(history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));$('command').value=history[historyIndex]||'';}if(e.key==='l'&&e.ctrlKey){e.preventDefault();$('terminal').textContent='';}};
$('device-select').onchange=e=>selectDevice(e.target.value);document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('search').oninput=renderCatalog;$('module').onchange=renderCatalog;Object.entries(moduleNames).forEach(([id,name])=>$('module').insertAdjacentHTML('beforeend',`<option value="${id}">${id} · ${name}</option>`));
$('check').onclick=()=>{renderObjectives();persist();renderCatalog();$('feedback').textContent=record.completed?'اكتمل التمرين. تم حفظ إنجازك.':'راجع الأهداف غير المكتملة، ثم أعد المحاولة.';};
$('reset').onclick=()=>{if(confirm('إعادة هذا النشاط ستمسح إعداداته وإنجازه المحفوظ. هل تريد المتابعة؟')){delete progress.labs[lab.id];loadLab(lab.id);toast('أُعيد النشاط إلى حالته الابتدائية.');}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wasla-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تصدير تقدّمك. يحتوي الملف على إعدادات التدريب.');};
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4_000_000)throw Error();const p=JSON.parse(await file.text());if(!validProgress(p))throw Error();if(!confirm('استبدال التقدّم الحالي بالنسخة المستوردة؟'))return;progress=p;loadLab(p.last);toast('تم استيراد التقدّم.');}catch{toast('تعذّر استيراد الملف. استخدم نسخة تقدّم صادرة من وصلة.');}finally{e.target.value='';}};
loadLab(progress.last);if(!storageOK)toast('الحفظ المحلي غير متاح أو تعذّر قراءة البيانات؛ صدّر التقدّم للاحتفاظ به.');
